use actix_web::{post, web, App, HttpResponse, HttpServer, Responder};
use serde::Deserialize;
use std::fs::File;
use std::io::{self, Read};
use std::path::PathBuf;

#[derive(Deserialize)]
struct SongRequest {
    filename: String,
}

#[post("/download")]
async fn download_song(song_request: web::Json<SongRequest>) -> impl Responder {
    let song_path = PathBuf::from(format!("/var/songs/{}", song_request.filename));

    // Check if the file exists
    if !song_path.exists() {
        return HttpResponse::NotFound().body("File does not exist");
    }

    // Attempt to read the file
    match File::open(&song_path) {
        Ok(mut file) => {
            let mut buffer = Vec::new();
            if let Err(_) = file.read_to_end(&mut buffer) {
                return HttpResponse::InternalServerError().body("Error reading file");
            }
            HttpResponse::Ok()
                .content_type("audio/mpeg")
                .body(buffer)
        }
        Err(_) => HttpResponse::InternalServerError().body("Error opening file"),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .service(download_song)
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}
