fn sanitize_filename(filename: &str) -> Option<String> {
    // Basic sanitization to prevent directory traversal attacks
    if filename.contains("..") || filename.contains("/") || filename.contains("\\") {
        None
    } else {
        Some(filename.to_string())
    }
}

